files.content:
* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #18231f;
  color: #f5f0df;
  font-synthesis: none;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 18px;
  display: grid;
  place-items: center;
  background-color: #18231f;
  background-image: radial-gradient(#34443b 1px, transparent 1px);
  background-size: 22px 22px;
}

.counter {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 42px);
  border: 2px solid #45594c;
  border-radius: 20px;
  background: #26352d;
  box-shadow: 0 16px 0 #111a16, 0 28px 60px #0b100dcc;
}

.header { text-align: center; }
.eyebrow, .section-label, footer {
  color: #a9bd9d;
  font-size: .82rem;
  font-weight: 750;
  letter-spacing: .14em;
}
h1 { margin: 10px 0 4px; font-size: clamp(1.65rem, 6vw, 2.25rem); line-height: 1.15; }
.subtitle { margin: 0; color: #c4c9b8; }

.current {
  margin: 30px 0 22px;
  padding: 20px;
  border: 2px dashed #68826b;
  border-radius: 14px;
  background: #1c2923;
  text-align: center;
}
.current output {
  display: block;
  margin-top: 5px;
  color: #f2c96d;
  font-size: clamp(3.5rem, 18vw, 5.5rem);
  font-weight: 850;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.button {
  min-height: 54px;
  padding: 12px 14px;
  border: 2px solid transparent;
  border-radius: 11px;
  font: inherit;
  font-size: 1rem;
  font-weight: 750;
  cursor: pointer;
  transition: transform .12s ease, filter .12s ease, box-shadow .12s ease;
}
.button-primary { color: #1d2a22; background: #f2c96d; box-shadow: 0 4px 0 #b38d3f; }
.button-secondary { color: #f5f0df; background: #526f5a; box-shadow: 0 4px 0 #344b3a; }
.button:hover { filter: brightness(1.08); transform: translateY(-1px); }
.button:active { transform: translateY(3px); box-shadow: none; }
.button:focus-visible { outline: 3px solid #fff4c5; outline-offset: 4px; }
.button:disabled { cursor: not-allowed; opacity: .58; filter: saturate(.55); transform: none; }
.status { min-height: 24px; margin: 15px 0 25px; color: #c4c9b8; text-align: center; }

.queue { padding-top: 20px; border-top: 1px solid #45594c; }
.queue-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 1.2rem; }
.count { padding: 6px 10px; border-radius: 999px; color: #1d2a22; background: #a9bd9d; font-weight: 750; font-variant-numeric: tabular-nums; }
.waiting-list { display: flex; flex-wrap: wrap; gap: 9px; margin: 17px 0 0; padding: 0; list-style: none; }
.waiting-list li {
  min-width: 54px;
  padding: 9px 12px;
  border: 1px solid #68826b;
  border-radius: 9px;
  color: #f2c96d;
  background: #1c2923;
  font-size: 1.05rem;
  font-weight: 800;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.empty-message { margin: 17px 0 0; color: #b4bdaf; }
footer { margin-top: 28px; text-align: center; font-size: .7rem; }

@media (max-width: 420px) {
  body { padding: 20px 12px; }
  .actions { grid-template-columns: 1fr; }
}

const takeButton = document.getElementById('take-ticket');
const serveButton = document.getElementById('serve-next');
const currentNumber = document.getElementById('current-number');
const waitingCount = document.getElementById('waiting-count');
const waitingList = document.getElementById('waiting-list');
const emptyMessage = document.getElementById('empty-message');
const status = document.getElementById('status');

let nextNumber = 1;
let current = null;
const waiting = [];

function render() {
  currentNumber.textContent = current ?? '—';
  waitingCount.textContent = waiting.length;
  waitingList.replaceChildren(...waiting.map((number) => {
    const item = document.createElement('li');
    item.textContent = number;
    return item;
  }));
  emptyMessage.hidden = waiting.length > 0;
  serveButton.disabled = waiting.length === 0;
}

takeButton.addEventListener('click', () => {
  const number = nextNumber++;
  waiting.push(number);
  status.textContent = `Ticket ${number} added to the waiting room.`;
  render();
});

serveButton.addEventListener('click', () => {
  if (waiting.length === 0) {
    status.textContent = 'No tickets are waiting.';
    return;
  }
  current = waiting.shift();
  status.textContent = `Now serving ticket ${current}.`;
  render();
});

render();
